import { useRef, useEffect, useState } from 'react'
import mapboxgl, { Marker } from 'mapbox-gl'
import Row from 'react-bootstrap/Row';
import Col from 'react-bootstrap/Col';
import Container from 'react-bootstrap/Container';
import Button from 'react-bootstrap/Button';

// eslint-disable-next-line 
import 'mapbox-gl/dist/mapbox-gl.css';
import './App.css';

import data from "./data/database.json"
import city from "./data/city.geojson"
import country_region from "./data/country_region.geojson"
import naturalfeatures from "./data/naturalfeatures.geojson"
import continent from "./data/continent.geojson"
import DramaCard from './dramaCard';
import githubLogo from "./data/github-mark.png"
import { MapboxExportControl, Size, PageOrientation, Format, DPI } from "@watergis/mapbox-gl-export";




function App() {



  const mapRef = useRef(null);
  const [selectedPoint, setSelectedPoint] = useState(null);
  const [selectedDrama, setSelectedDama] = useState(null);

  const [visibleLayers, setVisibleLayers] = useState({
    city: true,
    country_region: true,
    naturalfeatures: true,
    continent: true
  });



  const [mapboxMap, setMapboxMap] = useState(null);

  const baseURL = "https://dracor.org/eng/"



  useEffect(() => {

    mapboxgl.accessToken = process.env.REACT_APP_MAPBOX_ACCESS_TOKEN;
    const map = new mapboxgl.Map({
      container: mapRef.current,
      style: "mapbox://styles/andreaswagner/clhafhr30011701qu5t4e72iw",
      center: [13.404954, 52.520008], // Berlin
      zoom: 1,

    });


    setMapboxMap(map);

    // prevent the map from crossing the antimeridian
    // map.setMaxBounds([
    //   [-180, -90], // Southwest coordinates
    //   [180, 90] // Northeast coordinates
    // ]);

    map.addControl(new mapboxgl.NavigationControl(), 'top-right');
    map.addControl(new mapboxgl.FullscreenControl(), 'top-right');
    map.addControl(new mapboxgl.ScaleControl({
      maxWidth: 80,
      unit: 'metric'
    }), 'bottom-right');

    map.addControl(new MapboxExportControl({
      PageSize: Size.A2,
      PageOrientation: PageOrientation.Landscape,
      Format: Format.PNG,
      DPI: DPI[300],
      Crosshair: true,
      PrintableArea: true,


    }), 'top-left');


    map.on('load', () => {

      map.addSource('country_region', {
        type: 'geojson',
        data: country_region
      });
      map.addSource('naturalfeatures', {
        type: 'geojson',
        data: naturalfeatures
      });
      map.addSource('continent', {
        type: 'geojson',
        data: continent
      });
      map.addSource('city', {
        type: 'geojson',
        data: city
      });

      map.addLayer({
        id: 'city-layer',
        type: 'circle',
        source: 'city',
        paint: {
          'circle-radius': 6,
          'circle-color': '#007cbf',
          'circle-stroke-width': 1,
          'circle-stroke-color': '#fff',
          // 'circle-opacity': 0.8,
          'circle-radius': [
            'interpolate',
            ['linear'],
            ['get', 'count'],
            0, 4,
            10, 12,
            50, 18
          ],
        },

      });

      map.addLayer({
        id: 'country_region-layer',
        type: 'circle',
        source: 'country_region',
        paint: {
          'circle-radius': 6,
          'circle-color': '#955e00',
          'circle-stroke-width': 1,
          'circle-stroke-color': '#fff',
          // 'circle-opacity': 0.8,
          'circle-radius': [
            'interpolate',
            ['linear'],
            ['get', 'count'],
            0, 4,
            10, 12,
            50, 18
          ],
        }
      });

      map.addLayer({
        id: 'naturalfeatures-layer',
        type: 'circle',
        source: 'naturalfeatures',
        paint: {
          'circle-radius': [
            'interpolate',
            ['linear'],
            ['get', 'count'],
            0, 4,
            10, 12,
            50, 18
          ],
          'circle-color': '#30bf00',
          'circle-stroke-width': 1,
          'circle-stroke-color': '#fff',
          // 'circle-opacity': 0.8,
          "opacity": 0.5
        }
      });

      map.addLayer({
        id: 'continent-layer',
        type: 'circle',
        source: 'continent',
        paint: {
          'circle-radius': [
            'interpolate',
            ['linear'],
            ['get', 'count'],
            0, 4,
            10, 12,
            50, 18
          ],
          'circle-color': '#8945ae',
          'circle-stroke-width': 1,
          'circle-stroke-color': '#fff',
          // 'circle-opacity': 0.8,
        },

      });

      map.on('click', 'city-layer', (e) => selectClickedPoint(e, map));
      map.on('click', 'country_region-layer', (e) => selectClickedPoint(e, map));
      map.on('click', 'naturalfeatures-layer', (e) => selectClickedPoint(e, map));
      map.on('click', 'continent-layer', (e) => selectClickedPoint(e, map));
      map.on('mouseenter', 'city-layer', () => {
        map.getCanvas().style.cursor = 'pointer';
      });
      map.on('mouseleave', 'city-layer', () => {
        map.getCanvas().style.cursor = '';
      });
      map.on('mouseenter', 'country_region-layer', () => {
        map.getCanvas().style.cursor = 'pointer';
      });
      map.on('mouseleave', 'country_region-layer', () => {
        map.getCanvas().style.cursor = '';
      });
      map.on('mouseenter', 'naturalfeatures-layer', () => {
        map.getCanvas().style.cursor = 'pointer';
      });
      map.on('mouseleave', 'naturalfeatures-layer', () => {
        map.getCanvas().style.cursor = '';
      });
      map.on('mouseenter', 'continent-layer', () => {
        map.getCanvas().style.cursor = 'pointer';
      });
      map.on('mouseleave', 'continent-layer', () => {
        map.getCanvas().style.cursor = '';
      });

      // on the left of the map add a panel for switching each layer on and off

    });

  }, []);




  const selectClickedPoint = (e, map) => {
    const feature = e.features[0];
    setSelectedPoint(feature);
    const coordinates = feature.geometry.coordinates.slice();
    map.flyTo({
      center: coordinates,
      zoom: map.getZoom(),
      speed: 0.5
    });

  }

  const handleLayerToggle = (layer) => {
    const isVisible = visibleLayers[layer];
    setVisibleLayers({
      ...visibleLayers,
      [layer]: !isVisible
    });

    if (mapboxMap) {
      mapboxMap.setLayoutProperty(
        `${layer}-layer`,
        'visibility',
        isVisible ? 'none' : 'visible'
      );
    }
  }

  useEffect(() => {
    if (!mapboxMap) return;
    if (selectedPoint) {
      setSelectedPoint(null);
    }
    if (selectedDrama) {
      const dramaFilter = ["in", selectedDrama, ["get", "titles"]];
      mapboxMap.setFilter('city-layer', dramaFilter);
      mapboxMap.setFilter('country_region-layer', dramaFilter);
      mapboxMap.setFilter('naturalfeatures-layer', dramaFilter);
      mapboxMap.setFilter('continent-layer', dramaFilter);


    } else {
      mapboxMap.setFilter('city-layer', null);
      mapboxMap.setFilter('country_region-layer', null);
      mapboxMap.setFilter('naturalfeatures-layer', null);
      mapboxMap.setFilter('continent-layer', null);
    }

  }, [selectedDrama]);


  const resetMap = () => {
    setSelectedPoint(null);
    setSelectedDama(null);
    mapboxMap.flyTo({
      center: [13.404954, 52.520008], // Berlin
      zoom: 1,
      speed: 1,
      pitch: 0,
      bearing: 0,

    });
    // set all layers to visible
    setVisibleLayers({
      city: true,
      country_region: true,
      naturalfeatures: true,
      continent: true
    });
    mapboxMap.setLayoutProperty('city-layer', 'visibility', 'visible');
    mapboxMap.setLayoutProperty('country_region-layer', 'visibility', 'visible');
    mapboxMap.setLayoutProperty('naturalfeatures-layer', 'visibility', 'visible');
    mapboxMap.setLayoutProperty('continent-layer', 'visibility', 'visible');

    mapboxMap.setFilter('city-layer', null);
    mapboxMap.setFilter('country_region-layer', null);
    mapboxMap.setFilter('naturalfeatures-layer', null);
    mapboxMap.setFilter('continent-layer', null);



  }

  const downloadMapAsImage = () => {
    const mapContainer = document.getElementById('map-container');
    const mapCanvas = mapContainer.getElementsByClassName('mapboxgl-canvas')[0];

    if (mapCanvas) {
      console.log(mapCanvas);
      // download 
      var img = mapCanvas.toDataURL("image/png");
      var link = document.createElement('a');
      link.href = img;
      link.download = 'map.png';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      console.log("downloaded");
    }
    else {
      console.error('Map canvas not found');
    }
  }


  return (
    <div className="App">
      <header className="App-header" style={{ textAlign: "center" }}>
        <Row md={12} lg={12} className='justify-content-end' style={{ margin: "0", padding: "0", width: "100%" }}>
          <Col xs={12} md={10} lg={10} >
            <h1 style={{ fontSize: "2.5rem", marginBottom: "0.5rem" }}>A Little Atlas of Early Modern English Drama</h1>
          </Col>

          <Col xs={12} md={1} lg={1} >
            <Button
              className="btn btn-light"
              onClick={() => window.open('https://github.com/atlas-emed/atlas-emed.github.io/tree/react_app', '_blank')}
              style={{ margin: "0", padding: "5px" }}

            >
              <img src={githubLogo} alt="GitHub" style={{ width: '20px', height: '20px' }} />
            </Button>


          </Col>
          <Col xs={12} md={1} lg={1} >
            <Button
              className="btn btn-light"
              onClick={() => downloadMapAsImage()}
              style={{ margin: "0", padding: "5px" }}
            >
              <img src="https://img.icons8.com/ios-filled/50/000000/download-2.png" alt="Download" style={{ width: '20px', height: '20px' }} />
            </Button>
          </Col>

        </Row>


      </header>
      <Container fluid>
        <Row md={12} lg={12} >
          <Col xs={12} md={7} lg={7} >
            <div id='map-container' ref={mapRef} style={{ width: "100%" }} />
          </Col>
          <Col xs={12} md={5} lg={5} >
            <Row md={12} lg={12} >
              <Col xs={12} md={8} lg={8} >
                <div className="legend">
                  <div className="legend-item">
                    <span className="legend-color" style={{ backgroundColor: "#007cbf" }}></span>
                    <span className="legend-label">City</span>
                    <input type="checkbox" checked={visibleLayers.city} onChange={() => handleLayerToggle('city')} />
                  </div>
                  <div className="legend-item">
                    <span className="legend-color" style={{ backgroundColor: "#955e00" }}></span>
                    <span className="legend-label">Country/Region</span>
                    <input type="checkbox" checked={visibleLayers.country_region} onChange={() => handleLayerToggle('country_region')} />
                  </div>
                  <div className="legend-item">
                    <span className="legend-color" style={{ backgroundColor: "#30bf00" }}></span>
                    <span className="legend-label">Natural Feature</span>
                    <input type="checkbox" checked={visibleLayers.naturalfeatures} onChange={() => handleLayerToggle('naturalfeatures')} />
                  </div>
                  <div className="legend-item">
                    <span className="legend-color" style={{ backgroundColor: "#8945ae" }}></span>
                    <span className="legend-label">Continent</span>
                    <input type="checkbox" checked={visibleLayers.continent} onChange={() => handleLayerToggle('continent')} />
                  </div>
                </div>
              </Col>
              <Col xs={12} md={4} lg={4} >
                <Button className="btn btn-secondary" onClick={() => resetMap()}>
                  Reload Map
                </Button>
              </Col>

              <hr></hr>
            </Row>
            <Row md={12} lg={12} >
              {selectedPoint ? (
                <>
                  <h3>{selectedPoint.properties.name + " (" + selectedPoint.properties.original_label + ")"}</h3>
                  <p>Type: {selectedPoint.properties.type}</p>
                  {selectedPoint.properties.titles && (
                    <>
                      <Row>
                        <h4>Plays</h4>

                      </Row>
                      <div className="titles">
                        {JSON.parse(selectedPoint.properties.titles).map((title, index) => (
                          <DramaCard
                            key={index}
                            title={title}
                            setSelectedDama={setSelectedDama}
                            selectedDrama={selectedDrama}
                          />
                        ))}
                      </div>
                    </>
                  )}
                </>
              ) : (
                <>
                  {selectedDrama ? (
                    <>
                      <Row>
                        <Col>
                          <h4>Plays:</h4>
                        </Col>
                        <Col>
                          <Button className="btn btn-light" onClick={() => setSelectedDama(null)}>
                            Clear
                          </Button>
                        </Col>
                      </Row>
                      <div className="titles">

                        <DramaCard
                          title={selectedDrama}
                          setSelectedDama={setSelectedDama}
                          selectedDrama={selectedDrama}
                        />
                      </div>

                    </>
                  ) : (
                    <>
                      <p style={{ fontSize: "1.2rem", margin: 0, marginBottom: "10%", textAlign: "justify" }}>
                        This map charts most geographical items mentioned in about 400 early modern English plays. Move around, zoom, and click on any location to see the plays related to it and access them in the <a href="https://dracor.org/eng">English Drama Corpus (EngDraCor)</a>. Several types of toponyms (<span style={{ "color": "blue" }}>cities</span>, <span style={{ "color": "brown" }}>countries and regions</span>, <span style={{ "color": "purple" }}>continents</span>, and <span style={{ "color": "green" }}>natural features</span>) have been extracted through NLP methods and geocoded with <a href="https://nominatim.org"><i>Nominatim</i></a>, with extensive rounds of manual and LLM-assisted post-correction.<br />
                      </p>
                      <p style={{ fontSize: "1.1rem", margin: 0, marginBottom: "10%", textAlign: "justify" }}>
                        <b>Credits</b>: <a href="https://lucagiovannini7.github.io/index.html">Luca Giovannini</a> (conceptualization, data curation, supervision), <a href="https://www.dhss.phil.fau.de/person/andreas-wagner/">Andreas Wagner</a> (software, visualisation)
                        <br /><br />
                        <b>Paper</b>: Giovannini, Luca, and Andreas Wagner (2025). <a href="https://zenodo.org/records/15647553">"Prototyping an Atlas of Early Modern English Drama: An Experiment on DraCor Data"</a>. In: <i>AIUCD 2025 Book of Abstracts</i>. Università di Verona, 2025.
                      </p>
                    </>

                  )}
                </>


              )}
            </Row>


          </Col>
        </Row>

      </Container>

    </div>
  );
}

export default App;
